document.addEventListener('DOMContentLoaded', () => {
  /**
   * Sea View Villa - WordPress ACF Video Carousel
   *
   * Videos are loaded dynamically from:
   * window.seaViewVideos
   *
   * This array is generated by PHP from the ACF
   * "sea_videos" repeater field.
   */

  // ------------------------------------------------------------
  // Get video playlist from WordPress / ACF
  // ------------------------------------------------------------

  const videoPlaylist = Array.isArray(window.seaViewVideos)
    ? window.seaViewVideos.filter(Boolean)
    : [];

  // Stop if no videos are configured in ACF
  if (!videoPlaylist.length) {
    console.warn('Sea View Villa: No videos found in ACF.');
    return;
  }

  // ------------------------------------------------------------
  // DOM Elements
  // ------------------------------------------------------------

  const mainVideo = document.getElementById('mainVideo');
  const playOverlay = document.getElementById('playOverlay');
  const prevBtn = document.getElementById('prevVideo');
  const nextBtn = document.getElementById('nextVideo');
  const dotsContainer = document.getElementById('videoDots');

  if (!mainVideo) {
    console.warn('Sea View Villa: #mainVideo not found.');
    return;
  }

  let currentVideoIndex = 0;
  let isChangingVideo = false;

  // ------------------------------------------------------------
  // Helper: Update Video Dots
  // ------------------------------------------------------------

  function updateDots() {
    if (!dotsContainer) return;

    const dots = dotsContainer.querySelectorAll('.video-dot');

    dots.forEach((dot, index) => {
      dot.classList.toggle(
        'active',
        index === currentVideoIndex
      );
    });
  }

  // ------------------------------------------------------------
  // Helper: Show / Hide Play Overlay
  // ------------------------------------------------------------

  function showPlayOverlay() {
    if (playOverlay) {
      playOverlay.classList.remove('hidden');
    }
  }

  function hidePlayOverlay() {
    if (playOverlay) {
      playOverlay.classList.add('hidden');
    }
  }

  // ------------------------------------------------------------
  // Load Video
  // ------------------------------------------------------------

  function loadVideo(index, autoPlay = false) {
    if (!mainVideo || !videoPlaylist.length) return;

    // Keep index within range
    index =
      (index + videoPlaylist.length) %
      videoPlaylist.length;

    if (isChangingVideo) return;

    isChangingVideo = true;

    currentVideoIndex = index;

    const videoUrl = videoPlaylist[currentVideoIndex];

    // Fade out
    mainVideo.style.opacity = '0';

    // Stop current video
    mainVideo.pause();

    // Remove old source
    while (mainVideo.firstChild) {
      mainVideo.removeChild(mainVideo.firstChild);
    }

    // Create new source dynamically
    const source = document.createElement('source');

    source.src = videoUrl;

    // Detect common video type
    if (videoUrl.toLowerCase().includes('.webm')) {
      source.type = 'video/webm';
    } else if (videoUrl.toLowerCase().includes('.ogg')) {
      source.type = 'video/ogg';
    } else {
      source.type = 'video/mp4';
    }

    mainVideo.appendChild(source);

    // Reset video
    mainVideo.load();

    // Update dots immediately
    updateDots();

    // Show play button
    showPlayOverlay();

    // Wait for video metadata/data
    const handleLoaded = () => {
      mainVideo.style.opacity = '1';

      isChangingVideo = false;

      mainVideo.removeEventListener(
        'loadeddata',
        handleLoaded
      );

      if (autoPlay) {
        const playPromise = mainVideo.play();

        if (playPromise !== undefined) {
          playPromise.catch((error) => {
            console.log(
              'Video autoplay prevented:',
              error
            );

            showPlayOverlay();
          });
        }
      }
    };

    mainVideo.addEventListener(
      'loadeddata',
      handleLoaded
    );

    // Handle loading errors
    mainVideo.onerror = () => {
      isChangingVideo = false;

      mainVideo.style.opacity = '1';

      console.error(
        'Unable to load video:',
        videoUrl
      );

      showPlayOverlay();
    };
  }

  // ------------------------------------------------------------
  // Next Video
  // ------------------------------------------------------------

  function nextVideo() {
    const nextIndex =
      (currentVideoIndex + 1) %
      videoPlaylist.length;

    loadVideo(nextIndex, true);
  }

  // ------------------------------------------------------------
  // Previous Video
  // ------------------------------------------------------------

  function previousVideo() {
    const previousIndex =
      (currentVideoIndex - 1 + videoPlaylist.length) %
      videoPlaylist.length;

    loadVideo(previousIndex, true);
  }

  // ------------------------------------------------------------
  // Next Button
  // ------------------------------------------------------------

  if (nextBtn) {
    nextBtn.addEventListener('click', (event) => {
      event.preventDefault();
      nextVideo();
    });
  }

  // ------------------------------------------------------------
  // Previous Button
  // ------------------------------------------------------------

  if (prevBtn) {
    prevBtn.addEventListener('click', (event) => {
      event.preventDefault();
      previousVideo();
    });
  }

  // ------------------------------------------------------------
  // Video Dots
  // ------------------------------------------------------------

  if (dotsContainer) {
    dotsContainer.addEventListener('click', (event) => {
      const dot = event.target.closest('.video-dot');

      if (!dot) return;

      const index = parseInt(
        dot.dataset.index,
        10
      );

      if (Number.isNaN(index)) return;

      if (index !== currentVideoIndex) {
        loadVideo(index, true);
      }
    });
  }

  // ------------------------------------------------------------
  // Play Overlay
  // ------------------------------------------------------------

  if (playOverlay) {
    playOverlay.addEventListener('click', () => {
      const playPromise = mainVideo.play();

      if (playPromise !== undefined) {
        playPromise.catch((error) => {
          console.log(
            'Unable to play video:',
            error
          );
        });
      }
    });
  }

  // ------------------------------------------------------------
  // Video Events
  // ------------------------------------------------------------

  mainVideo.addEventListener('play', () => {
    hidePlayOverlay();
  });

  mainVideo.addEventListener('pause', () => {
    if (!mainVideo.ended) {
      showPlayOverlay();
    }
  });

  mainVideo.addEventListener('ended', () => {
    nextVideo();
  });

  // ------------------------------------------------------------
  // Touch Swipe
  // ------------------------------------------------------------

  const videoWrapper = document.querySelector(
    '.video-player-container'
  );

  if (videoWrapper) {
    let touchStartX = 0;
    let touchStartY = 0;

    videoWrapper.addEventListener(
      'touchstart',
      (event) => {
        if (!event.changedTouches.length) return;

        touchStartX =
          event.changedTouches[0].screenX;

        touchStartY =
          event.changedTouches[0].screenY;
      },
      { passive: true }
    );

    videoWrapper.addEventListener(
      'touchend',
      (event) => {
        if (!event.changedTouches.length) return;

        const touchEndX =
          event.changedTouches[0].screenX;

        const touchEndY =
          event.changedTouches[0].screenY;

        const differenceX =
          touchEndX - touchStartX;

        const differenceY =
          touchEndY - touchStartY;

        // Ignore vertical scrolling
        if (
          Math.abs(differenceX) <=
          Math.abs(differenceY)
        ) {
          return;
        }

        // Minimum swipe distance
        if (Math.abs(differenceX) < 50) {
          return;
        }

        if (differenceX < 0) {
          nextVideo();
        } else {
          previousVideo();
        }
      },
      { passive: true }
    );
  }

  // ------------------------------------------------------------
  // Initialize
  // ------------------------------------------------------------

  updateDots();

  // Load first ACF video
  loadVideo(0, false);
});